WITH matched AS (SELECT * FROM security_events WHERE rule_name IN ('recon-whoami', 'recon-ipconfig') AND time >= NOW() - INTERVAL '300 seconds'), ordered_1 AS (SELECT *, MIN(CASE WHEN rule_name = 'recon-whoami' THEN time END) OVER (PARTITION BY "User") AS __step_1 FROM matched), ordered_2 AS (SELECT *, MIN(CASE WHEN rule_name = 'recon-ipconfig' AND time >= __step_1 THEN time END) OVER (PARTITION BY "User") AS __step_2 FROM ordered_1) SELECT "User", COUNT(DISTINCT rule_name) AS distinct_rules, MIN(time) AS first_seen, MAX(time) AS last_seen FROM ordered_2 GROUP BY "User" HAVING COUNT(DISTINCT rule_name) >= 2 AND MAX(__step_2) IS NOT NULL
